"""Observe C++ node addresses and state; preserve candidate-owned lifetime."""
from harness_random04 import uniform_parts
CORE=r'''
#include <memory>
#include <unordered_map>
#include <unordered_set>
#include <type_traits>
namespace Nodes4 {
struct Snapshot{RandomNode* root;std::vector<RandomNode*> nodes,left,right;std::vector<int> data,values;std::unordered_map<RandomNode*,int> rank;};
void check(bool ok,const std::string& message){if(!ok)throw std::runtime_error(message);}
Snapshot take(RandomBst& actor){Snapshot out;out.root=actor.Root;std::vector<RandomNode*> pending;if(out.root)pending.push_back(out.root);std::unordered_set<RandomNode*> seen;while(!pending.empty()){auto node=pending.back();pending.pop_back();check(seen.insert(node).second&&out.nodes.size()<1000,"Root must be a finite proper tree");out.nodes.push_back(node);out.data.push_back(node->Data);out.left.push_back(node->Left);out.right.push_back(node->Right);if(node->Right)pending.push_back(node->Right);if(node->Left)pending.push_back(node->Left);}std::vector<RandomNode*> stack;auto current=out.root;while(current||!stack.empty()){while(current){stack.push_back(current);current=current->Left;}current=stack.back();stack.pop_back();check(out.values.empty()||out.values.back()<=current->Data,"Maintain BST inorder");out.rank.emplace(current,static_cast<int>(out.values.size()));out.values.push_back(current->Data);current=current->Right;}return out;}
json query(RandomBst& actor,const Snapshot& before,RandomNode* node){check(actor.Root==before.root,"Queries preserve Root");for(size_t i=0;i<before.nodes.size();++i){auto old=before.nodes[i];check(old->Data==before.data[i]&&old->Left==before.left[i]&&old->Right==before.right[i],"Queries preserve Data and links");}check(!node||before.rank.count(node),"Return actual current node");return node?json::array({node->Data}):json::array();}
json basic(RandomBst& actor,const std::string& operation,const json& args){static_assert(std::is_same_v<decltype(actor.Insert(0)),void>);static_assert(std::is_same_v<decltype(actor.Delete(0)),bool>);static_assert(std::is_same_v<decltype(actor.Find(0)),RandomNode*>);static_assert(std::is_same_v<decltype(actor.GetRandomNode()),RandomNode*>);if(operation=="Insert"){actor.Insert(args[0].get<int>());return nullptr;}if(operation=="Delete")return actor.Delete(args[0].get<int>());auto before=take(actor);if(operation=="Find")return query(actor,before,actor.Find(args[0].get<int>()));if(operation=="GetRandomNode")return query(actor,before,actor.GetRandomNode());throw std::runtime_error("Unknown operation");}
json delta(const std::vector<int>& before,const std::vector<int>& after){size_t i=0,j=0;auto added=json::array(),removed=json::array();while(i<before.size()&&j<after.size()){if(before[i]==after[j]){++i;++j;}else if(before[i]<after[j])removed.push_back(before[i++]);else added.push_back(after[j++]);}while(i<before.size())removed.push_back(before[i++]);while(j<after.size())added.push_back(after[j++]);return json{{"added",added},{"removed",removed},{"count",after.size()}};}
json operations,arguments;std::vector<int> values;
std::unique_ptr<RandomBst> build(){auto actor=std::make_unique<RandomBst>();for(size_t i=1;i<operations.size();++i)basic(*actor,operations[i].get<std::string>(),arguments[i]);return actor;}
}
class Solution_4_11 {std::unique_ptr<RandomBst> actor;public:void Shuffle(std::vector<int>& array){if(!actor)actor=Nodes4::build();auto before=Nodes4::take(*actor);Nodes4::check(before.values==Nodes4::values&&array.size()==before.values.size(),"Preserve operation-prefix multiset");auto chosen=actor->GetRandomNode();Nodes4::query(*actor,before,chosen);if(array.empty()){Nodes4::check(!chosen,"Empty query returns null");return;}Nodes4::check(chosen,"Nonempty query returns current node");int selected=before.rank.at(chosen);std::vector<int> remaining;for(size_t i=0;i<array.size();++i)if(static_cast<int>(i)!=selected)remaining.push_back(static_cast<int>(i));for(int i=static_cast<int>(remaining.size())-1;i>0;--i){int other=RandomSource::GetRandom(0,i);std::swap(remaining[i],remaining[other]);}array[0]=selected;std::copy(remaining.begin(),remaining.end(),array.begin()+1);}};
'''
ENDING=r'''
json executeRandomBst4(const json& row){const auto& ops=row["arguments"][0];const auto& argv=row["arguments"][1];std::uint32_t seed=0x411b57;RandomSource::Draw=[&seed](int lower,int upper){Nodes4::check(0<=lower&&lower<=upper,"Use valid inclusive bounds");seed=seed*1664525u+1013904223u;return lower+static_cast<int>((static_cast<std::uint64_t>(seed)*(static_cast<std::uint64_t>(upper)-lower+1))>>32);};RandomBst actor;auto before=Nodes4::take(actor);json results=json::array({nullptr}),changes=json::array({Nodes4::delta({},before.values)});for(size_t i=1;i<ops.size();++i){std::string operation=ops[i];if(operation=="GetRandomNode"){Nodes4::operations=json::array();Nodes4::arguments=json::array();for(size_t j=0;j<i;++j){Nodes4::operations.push_back(ops[j]);Nodes4::arguments.push_back(argv[j]);}Nodes4::values=before.values;auto saved=RandomSource::Draw;std::vector<int> labels(before.values.size());for(size_t j=0;j<labels.size();++j)labels[j]=static_cast<int>(j);try{RandomAudit4_11::run(json{{"arguments",json::array({labels})}});}catch(...){RandomSource::Draw=saved;throw;}RandomSource::Draw=saved;Nodes4::check(actor.Root==before.root,"Instances own independent state");}results.push_back(Nodes4::basic(actor,operation,argv[i]));auto after=Nodes4::take(actor);changes.push_back(Nodes4::delta(before.values,after.values));before=std::move(after);}return json{{"actual",{{"results",results},{"finalValues",before.values}}},{"changes",changes},{"mutationOk",true},{"uniformOk",true}};}
'''
def parts(code):
    outside,inside=uniform_parts('cpp',code+CORE)
    return outside+ENDING,inside
